// Normalise Sent -- n8n Code node (Run Once for All Items).
//
// Turns a batch of Sent-folder messages from the IMAP trigger into rows for
// mailbox_sent. It is the IMAP pre-flight's reading, kept current: when each
// message went, and whether it counts toward Section 5's warm-up ceiling. A
// message counts ("external") when any recipient is someone other than:
//   - an address on the mailbox's own domain -- a note to yourself or to a
//     colleague warms nothing;
//   - the operator's own notification address -- Mailbox Watch's reply
//     notifications go there, and they are not mail to a cold prospect
//     (operator decision, 2026-09-15). It comes from the `settings` table,
//     via Load Settings, at runtime; nothing is baked in.
//
// The trigger delivers the Sent folder in batches of up to 20, and re-reads the
// whole folder on every activation (so manual sends made while n8n was down are
// picked up). Every row is keyed on Message-ID, so re-delivery is a no-op.

const OWN_DOMAIN = "amitrixlabs.com";

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function domainOf(addr) {
  const s = str(addr).toLowerCase();
  const i = s.lastIndexOf('@');
  return i === -1 ? '' : s.slice(i + 1);
}

// Every address in a raw header value -- 'Name <first>, second' gives
// [first, second] -- lower-cased and de-duplicated.
function addresses(v) {
  const found = String(v === null || v === undefined ? '' : v).match(/[^\s<>,;:"'()\[\]]+@[^\s<>,;:"'()\[\]]+/g) || [];
  const out = [];
  for (let i = 0; i < found.length; i++) {
    const a = found[i].toLowerCase().replace(/\.+$/, '');
    if (out.indexOf(a) === -1) out.push(a);
  }
  return out;
}

// Message-IDs are stored with their angle brackets, exactly as nodemailer
// returns them and as In-Reply-To carries them, so every table compares like
// with like.
function messageId(v) {
  const m = str(v).match(/<[^<>\s]+>/);
  if (m) return m[0];
  const s = str(v).split(/\s+/)[0].replace(/[<>]/g, '');
  return s ? '<' + s + '>' : '';
}

// A message with no Message-ID still went out and still counts. Key it on what
// it is, so the next re-read maps it to the same row instead of adding one.
function fallbackId(j) {
  const s = [str(j.date), str(j.to), str(j.cc), str(j.subject)].join('|');
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return '<no-message-id.' + h.toString(16) + '@mirror.invalid>';
}

// The one rule for "does sending to this recipient warm the domain".
function countsTowardCeiling(addr, operator) {
  return domainOf(addr) !== OWN_DOMAIN && addr !== operator;
}

function sentRows(messages, operatorEmail) {
  const operator = str(operatorEmail).toLowerCase();
  const rows = [];
  let undated = 0;
  for (let i = 0; i < messages.length; i++) {
    const j = messages[i] || {};
    const meta = j.metadata || {};
    const t = new Date(str(j.date)).getTime();
    if (!str(j.date) || isNaN(t)) {
      // The pre-flight fell back to INTERNALDATE here; the trigger does not
      // expose it. Counted and reported rather than guessed.
      undated++;
      continue;
    }
    const recipients = addresses(j.to).concat(addresses(j.cc), addresses(meta.bcc)).filter(function (a, k, all) {
      return all.indexOf(a) === k;
    });
    rows.push({
      message_id: messageId(meta['message-id']) || fallbackId(j),
      sent_at: new Date(t).toISOString(),
      recipients: recipients,
      external: recipients.some(function (a) { return countsTowardCeiling(a, operator); }),
    });
  }
  return { rows: rows, seen: messages.length, undated: undated };
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

// Load Settings sits between the trigger and this node: it runs once per batch
// and hands on its one row, so the messages themselves are read back from the
// trigger node by name.
const settings = $input.first().json;
const messages = $('Sent Folder').all().map(function (it) { return it.json; });
return [{ json: { payload: sentRows(messages, settings.operator_email) } }];

// Classify Inbound -- generated by n8n/sendtrack/build_workflow.py.
// Part 1, verbatim: n8n/sendtrack/code_operator_command.js above its 'Node body' marker --
// the operator-command parser and its authentication gate (Section 9, Workflow 7).
// Part 2: n8n/sendtrack/code_classify_reply.js.

// Operator command parsing -- the library half of Classify Inbound.
//
// Section 9, Workflow 7. The operator approves a drafted reply by answering the
// review email: "APPROVE <code>", "REJECT <code>", or "EDIT <code>" followed by
// the replacement text. This file decides, from one INBOX message, whether it
// LOOKS like such a command and whether its authentication passes.
//
// WHY THIS RUNS BEFORE REPLY CLASSIFICATION. code_classify_reply.js treats "no"
// as the first word of a message as an opt-out, and Record Inbound blocklists
// the matched lead's domain permanently. The operator's answers arrive in the
// same mailbox, and an operator who replies to the review email is replying
// INSIDE the prospect's thread -- the review email quotes it, so the References
// header carries our own Message-ID and Record Inbound's strongest matcher
// (`thread`) would tie that message to the prospect's lead. A one-word "no"
// from the operator would then blocklist a real prospect, permanently, with no
// error anywhere. So the command check is first and it is a hard fork: a
// message that is an operator command is never classified as a prospect reply,
// and a message that is not one never reaches the approval path.
//
// WHAT THIS FILE DOES NOT DECIDE. It never compares the sender with the
// operator's address: that address is runtime data in the `settings` table
// (migration 008) and must not be baked into workflow JSON, so the comparison
// happens in SQL, in the same statement that records the command. This file
// reports `from_addr` and the authentication result and lets that statement
// judge. It fails closed everywhere: an unparseable or absent
// Authentication-Results header is not a pass.

// Section 5 / Section 9: an approval counts only if the message's
// authentication results show SPF and DKIM pass. Measured against the real
// header Zoho writes (n8n execution 2336, the Pharmahungary reply):
//
//   authentication-results: mx.zohomail.com;\tdkim=pass;\tspf=pass (zohomail.com:
//   domain of pharmahungary.com designates 185.51.190.242 as permitted sender)
//   smtp.mailfrom=...; dmarc=pass(p=none dis=none) header.from=pharmahungary.com
//
// so the method results are `<method>=<result>` separated by tabs or semicolons,
// each optionally followed by a parenthesised comment. `spf=pass` inside that
// comment text is a real possibility ("... designates ... as permitted sender"
// does not contain it, but nothing stops a future comment from doing so), so
// the comments are stripped before the methods are read.
//
// ARC-Authentication-Results is deliberately NOT consulted. It records what some
// earlier hop claims to have seen, which is a different and weaker statement
// than what our own mail host verified, and this is the gate on sending mail to
// a prospect.
const AUTH_METHODS = ['spf', 'dkim'];

// APPROVE/REJECT/EDIT and the code, on the first line that carries one. Case is
// ignored on the verb (a phone mail client may capitalise or not) but the code's
// alphabet is upper case only -- migration 017 pins the shape.
const COMMAND_VERBS = ['APPROVE', 'REJECT', 'EDIT'];
const CODE_RE = /\bNS-[23456789ABCDEFGHJKMNPQRSTVWXYZ]{10}\b/;
const COMMAND_RE = /^\s*(approve|reject|edit)\b[\s:,-]*(NS-[23456789abcdefghjkmnpqrstvwxyz]{10})?\s*(.*)$/i;

function opStr(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

// Drop every parenthesised comment, including nested ones, so a method result is
// read from the header's own tokens and never from prose inside a comment.
function stripComments(s) {
  let out = '';
  let depth = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charAt(i);
    if (c === '(') { depth++; continue; }
    if (c === ')') { if (depth > 0) depth--; continue; }
    if (depth === 0) out += c;
  }
  return out;
}

// One Authentication-Results header (or several, joined) -> { spf: bool, dkim: bool }.
// A method named more than once must pass EVERY time: two headers disagreeing
// about SPF is not a pass.
function authResults(header) {
  const text = stripComments(opStr(header)).toLowerCase();
  const seen = {};
  const re = /([a-z][a-z0-9-]*)\s*=\s*([a-z]+)/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const method = m[1];
    const result = m[2];
    if (AUTH_METHODS.indexOf(method) === -1) continue;
    const ok = result === 'pass';
    seen[method] = seen[method] === undefined ? ok : (seen[method] && ok);
  }
  const out = {};
  for (let i = 0; i < AUTH_METHODS.length; i++) {
    out[AUTH_METHODS[i]] = seen[AUTH_METHODS[i]] === true;
  }
  return out;
}

// What the operator wrote, above any quoted thread. freshText() already does
// that cut for prospect replies; the command parser is handed the same text so
// an APPROVE quoted back inside a later message is not re-read as a command.
//
// EDIT's replacement is everything after the code -- the rest of that line and
// every following line of fresh text. Blank means "no replacement given", which
// the caller refuses rather than guessing.
function parseCommand(fresh) {
  const lines = opStr(fresh).replace(/\r\n?/g, '\n').split('\n');
  for (let i = 0; i < lines.length; i++) {
    const m = COMMAND_RE.exec(lines[i]);
    if (!m) continue;
    const verb = m[1].toUpperCase();
    if (COMMAND_VERBS.indexOf(verb) === -1) continue;

    // The verb is on this line. The code is normally on it too; accept it on a
    // following line as well, because a client may wrap a long line. Whatever
    // follows the code -- the rest of its line and every later line -- is the
    // replacement text, for EDIT.
    let code = null;
    let after = '';
    if (m[2]) {
      code = m[2].toUpperCase();
      after = [opStr(m[3])].concat(lines.slice(i + 1)).join('\n');
    } else {
      const tail = lines.slice(i + 1).join('\n');
      const hit = CODE_RE.exec(tail.toUpperCase());
      if (hit) {
        code = hit[0];
        after = tail.slice(hit.index + hit[0].length);
      } else {
        after = [opStr(m[3])].concat(lines.slice(i + 1)).join('\n');
      }
    }
    after = after.trim();
    return {
      is_command: true,
      command: verb,
      code: code,
      // Only EDIT carries a replacement; migration 017 refuses one on the others.
      replacement: verb === 'EDIT' ? (after || null) : null,
    };
  }
  return { is_command: false, command: null, code: null, replacement: null };
}

// The whole decision for one message, as the SQL statement needs it. `sender_ok`
// is left to SQL -- see the header comment.
function operatorCommand(j, fresh) {
  const meta = (j && j.metadata) || {};
  const parsed = parseCommand(fresh);
  const auth = authResults(meta['authentication-results']);

  // Why it would be refused, in the order the operator would want to hear it.
  // `sender` is the one reason this file cannot rule on, so it is reported as a
  // pending check rather than a verdict.
  let refused = null;
  if (parsed.is_command && !parsed.code) refused = 'no one-time code in the message';
  else if (parsed.is_command && !auth.spf) refused = 'the message\'s authentication results do not show SPF pass';
  else if (parsed.is_command && !auth.dkim) refused = 'the message\'s authentication results do not show DKIM pass';
  else if (parsed.is_command && parsed.command === 'EDIT' && !parsed.replacement) {
    refused = 'EDIT with no replacement text after the code';
  }

  return {
    is_command: parsed.is_command,
    command: parsed.command,
    code: parsed.code,
    replacement: parsed.replacement,
    spf_pass: auth.spf,
    dkim_pass: auth.dkim,
    refused_reason: refused,
  };
}

// ---------------------------------------------------------------------------
// The decision -- Decide Command, n8n Code node (Run Once for Each Item).
//
// Everything above this point can be read off one message. The three things
// that cannot -- is the sender the operator's address, does this code exist, is
// it unused and unexpired -- are database facts, and "Load Command Context" has
// just read them in one read-only snapshot. This section turns that snapshot
// into a verdict.
//
// It is NOT the last line of defence. "Apply Operator Command" re-derives the
// operator address from `settings`, re-checks the code through
// reply_approval_usable(), and the table itself CHECKs that `accepted` is only
// possible with SPF, DKIM and the sender all passing (migration 017). A bug
// here can refuse a real approval; it cannot accept a forged one -- the same
// direction of safety as Decide Send and Claim Send.
//
// THREE SEPARATE QUESTIONS, and conflating them is how a prospect's reply would
// get lost, or a prospect's domain blocklisted by the operator's own "no":
//
//   record   -- is this message command-SHAPED? Then it goes into
//               operator_commands, accepted or refused. The refused rows are
//               the point: a spoofed sender, a failed SPF or DKIM, an unknown,
//               expired or reused code (migration 017).
//   handled  -- is it really FROM the operator (SPF + DKIM + the operator's own
//               address)? Then it is operator mail and is never classified as a
//               prospect reply. Anything else falls through to Record Inbound,
//               which is right: a message that merely looks like a command and
//               did not come from the operator may well be a prospect writing.
//   accepted -- handled, and nothing refused it. Only then does a draft move.
//
// A message from the operator that is NOT command-shaped -- a plain "no" --
// records nothing and is handled=false, so it reaches Record Inbound. That
// statement has its own guard: a message from the operator's address is never
// matched to a lead, so the "no" cannot blocklist a prospect (Workflow 6).

// Section 5, substituted at build time: the signature every outbound message
// carries, and the one-URL cap. An EDIT replaces the reply's core text and
// keeps the frame around it, so the operator's own words go out under the same
// signature and the send path's checks still find what they look for.
const CMD_SIGNATURE = "Abdullah Amir\nFounder, Amitrix Labs\n+923178485713";
const CMD_MAX_URLS = 1;
const CMD_URL_RE = /\b(?:https?:\/\/|www\.)[^\s<>()]+/gi;

const CMD_OUTCOME = { APPROVE: 'approved', REJECT: 'rejected', EDIT: 'edited' };

function cmdUrls(v) {
  return (opStr(v).match(CMD_URL_RE) || []).length;
}

function cmdMs(v) {
  if (v === null || v === undefined || v === '') return null;
  const t = new Date(v).getTime();
  return isNaN(t) ? null : t;
}

// The reply as it will go out, with the operator's text in place of the
// model's. The frame is taken from the stored draft, never regenerated: the
// greeting is its first paragraph, and everything from the signature onward --
// the signature itself and the quoted message being answered -- is kept
// verbatim. So an EDIT changes exactly the words the operator rewrote.
function framedEdit(body, replacement) {
  const b = String(body === null || body === undefined ? '' : body).replace(/\r\n?/g, '\n');
  const at = b.indexOf(CMD_SIGNATURE);
  const tail = at === -1 ? '' : b.slice(at + CMD_SIGNATURE.length);
  const firstBreak = b.indexOf('\n\n');
  const greeting = firstBreak === -1 ? 'Hello,' : b.slice(0, firstBreak).trim();
  return [greeting, '', opStr(replacement), '', CMD_SIGNATURE].join('\n') + tail;
}

function commandDecision(ctx) {
  const cmd = (ctx && ctx.command) || {};
  const isCommand = cmd.is_command === true;
  const spf = cmd.spf_pass === true;
  const dkim = cmd.dkim_pass === true;
  const operator = opStr(ctx.operator_email).toLowerCase();
  const from = opStr(ctx.payload && ctx.payload.from_addr).toLowerCase();
  const senderOk = operator !== '' && from !== '' && from === operator;
  const authenticated = isCommand && spf && dkim && senderOk;
  const verb = opStr(cmd.command).toUpperCase();
  const code = opStr(cmd.code).toUpperCase() || null;
  const now = cmdMs(ctx.now);
  const expires = cmdMs(ctx.code_expires_at);

  let edited = null;
  let refused = null;
  if (!isCommand) {
    refused = 'not an operator command';
  } else if (cmd.refused_reason) {
    // No code in the message, SPF or DKIM not passing, or EDIT with no
    // replacement text: decided from the message alone, above.
    refused = cmd.refused_reason;
  } else if (!senderOk) {
    refused = operator
      ? 'not sent from the operator address'
      : 'no operator address is configured (settings.operator_email)';
  } else if (!ctx.code_found) {
    refused = 'no such one-time code';
  } else if (ctx.code_used_at) {
    refused = 'that one-time code was already used at ' + opStr(ctx.code_used_at) +
      ' (' + opStr(ctx.code_outcome) + ')';
  } else if (expires !== null && now !== null && expires <= now) {
    refused = 'that one-time code expired at ' + opStr(ctx.code_expires_at);
  } else if (opStr(ctx.draft_status) !== 'pending') {
    refused = 'draft ' + opStr(ctx.draft_id) + ' is no longer waiting (it is ' +
      (opStr(ctx.draft_status) || 'gone') + ')';
  } else if (verb === 'EDIT') {
    edited = framedEdit(ctx.draft_body, cmd.replacement);
    if (cmdUrls(edited) > CMD_MAX_URLS) {
      // Section 5 allows one plain URL. Refused rather than sent -- and the
      // code is NOT used, so the same code still works for a corrected EDIT.
      refused = 'that replacement carries ' + cmdUrls(edited) + ' links; Section 5 allows ' +
        CMD_MAX_URLS + '. The code is still good: send EDIT again with at most one link.';
      edited = null;
    }
  }

  // `accepted` here is a PROPOSAL. Apply Operator Command re-derives the
  // operator address, re-checks the code through reply_approval_usable() and
  // only then moves the draft; what actually happened is what that statement
  // returns, and Build Command Ack writes the acknowledgement from THAT, never
  // from this.
  const accepted = authenticated && refused === null;

  return {
    // operator_commands gets a row for anything command-shaped.
    record: isCommand,
    // Operator mail is never a prospect reply.
    handled: authenticated,
    accepted: accepted,
    command: verb || null,
    code: code,
    replacement: verb === 'EDIT' ? (cmd.replacement || null) : null,
    edited_body: edited,
    spf_pass: spf,
    dkim_pass: dkim,
    sender_ok: senderOk,
    refused_reason: refused,
    outcome: accepted ? (CMD_OUTCOME[verb] || null) : null,
    draft_id: ctx.draft_id === undefined ? null : ctx.draft_id,
    code_kind: ctx.code_kind === undefined ? null : ctx.code_kind,
  };
}

// ---------------------------------------------------------------------------

// Classify Inbound -- n8n Code node (Run Once for Each Item).
//
// Section 9, Workflow 6: "Any reply -> kill follow-up sequence, set
// status='replied'. Opt-out detection: reply matching no/unsubscribe/remove/
// stop -> add domain to blocklist, permanent." Section 5 makes that opt-out the
// basis of the GDPR/KVKK legitimate-interest position, so it is honoured the
// moment it is seen.
//
// Deterministic, no model (build rule 3). What decides the outcome is the text
// the person actually WROTE, not the message they sent back. Every reply quotes
// our email, and our email says "reply 'no'" -- classify the whole body and
// every single reply is an opt-out. So the quoted part is cut first, and the
// opt-out sentence is stripped again afterwards in case a client quoted it
// without a marker.
//
// Precedence: bounce > auto-reply > opt-out > reply. A bounce or an
// out-of-office is not a person answering, so neither sets 'replied' -- an
// out-of-office must not kill the follow-up sequence.

// Section 5 / Section 9 opt-out words -- parsed from the doc and checked at
// build time. "no" counts only as the FIRST word of what they wrote ("No,
// thanks" opts out; "we have no chatbot, tell me more" does not). The other
// three count anywhere in their text.
const OPT_OUT_KEYWORDS = ['no', 'unsubscribe', 'remove', 'stop'];
const OPT_OUT = "If this isn't relevant, reply 'no' and I won't follow up.";
const OWN_DOMAIN = "amitrixlabs.com";

// The first-word "no" in the languages of Section 12's geographies: the person
// following our instruction may not answer in English. Czech "ne" is left out
// on purpose -- it opens ordinary Turkish questions ("Ne zaman...?", "when..."),
// and a false opt-out blocklists a lead permanently.
const NO_WORDS = ['no', 'nope', 'não', 'nao', 'nie', 'hayır', 'hayir', 'nem', 'nu'];

// Replies from these are a person, not a company: the domain is never matched
// to a lead and never blocklisted.
const FREEMAIL = [
  'gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.co.in', 'yahoo.com.br', 'yahoo.com.mx',
  'yahoo.com.ar', 'yahoo.ro', 'hotmail.com', 'outlook.com', 'live.com', 'msn.com', 'icloud.com',
  'me.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'gmx.net', 'yandex.com',
  'mail.ru', 'mail.com', 'zoho.com', 'zohomail.com', 'rediffmail.com', 'wp.pl', 'o2.pl',
  'onet.pl', 'interia.pl', 'seznam.cz', 'freemail.hu', 'citromail.hu', 'uol.com.br',
  'bol.com.br', 'terra.com.br',
];

// "On Mon, 14 Sep 2026, X wrote:" and its equivalents in the leads' languages.
const QUOTE_HEADER = /(wrote|escribi[óo]|a [ée]crit|schrieb|escreveu|ha scritto|yazd[ıi]|napisa[łl](?:\(a\)|a)?|[íi]rta|napsal(?:\(a\)|a)?|a scris)\s*:\s*$/i;
const QUOTE_OPENER = /^\s*(on|el|le|am|em|il)\b/i;
const SEPARATOR = /^\s*(?:-{2,}\s*(?:original message|forwarded message|mensaje original|mensagem original|message d'origine)\s*-{2,}|_{10,})\s*$/i;
const OUTLOOK_FROM = /^\s*(from|de|von|od|kimden|feladó|expeditor)\s*:\s*\S/i;
const OUTLOOK_NEXT = /^\s*(sent|date|to|subject|enviado|fecha|para|asunto|gesendet|datum|an|betreff|wysłano|data|do|temat|tarih|kime|konu)\s*:/i;

const AUTO_SUBJECT = /^(?:auto(?:matic)?[ -]?(?:reply|response|antwort)|out of (?:the )?office|ooo\b|abwesenheit|fuera de (?:la )?oficina|respuesta autom|resposta autom|r[ée]ponse automatique|otomatik yan[ıi]t|automatyczna odpowied|automatick[áa] odpov|automatikus v[áa]lasz|r[ăa]spuns automat)/i;
const BOUNCE_SUBJECT = /undeliver|delivery status notification|returned mail|failure notice|delivery (?:has )?failed|mail delivery failed|non[- ]?delivery|could not be delivered/i;

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function domainOf(addr) {
  const s = str(addr).toLowerCase();
  const i = s.lastIndexOf('@');
  return i === -1 ? '' : s.slice(i + 1);
}

function addresses(v) {
  const found = String(v === null || v === undefined ? '' : v).match(/[^\s<>,;:"'()\[\]]+@[^\s<>,;:"'()\[\]]+/g) || [];
  const out = [];
  for (let i = 0; i < found.length; i++) {
    const a = found[i].toLowerCase().replace(/\.+$/, '');
    if (out.indexOf(a) === -1) out.push(a);
  }
  return out;
}

function messageId(v) {
  const m = str(v).match(/<[^<>\s]+>/);
  if (m) return m[0];
  const s = str(v).split(/\s+/)[0].replace(/[<>]/g, '');
  return s ? '<' + s + '>' : '';
}

// Every <...@...> token: In-Reply-To + References for a reply, the whole NDR
// body for a bounce (which quotes the original headers).
function messageIds(v) {
  const found = String(v || '').match(/<[^<>\s@]+@[^<>\s]+>/g) || [];
  return found.filter(function (x, i) { return found.indexOf(x) === i; });
}

function fallbackId(j) {
  const s = [str(j.date), str(j.from), str(j.subject)].join('|');
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return '<no-message-id.' + h.toString(16) + '@inbound.invalid>';
}

function stripHtml(h) {
  return String(h || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|blockquote)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&');
}

// What they wrote above the quoted thread.
function freshText(text) {
  const lines = String(text || '').replace(/\r\n?/g, '\n').split('\n');
  let cut = lines.length;
  for (let i = 0; i < lines.length; i++) {
    const ln = lines[i];
    if (QUOTE_HEADER.test(ln)) {
      // Gmail wraps a long header over two lines: "On ..., X <" / "x@y> wrote:".
      cut = (i > 0 && !QUOTE_OPENER.test(ln) && QUOTE_OPENER.test(lines[i - 1])) ? i - 1 : i;
      break;
    }
    if (SEPARATOR.test(ln)) { cut = i; break; }
    if (OUTLOOK_FROM.test(ln) && lines.slice(i + 1, i + 5).some(function (w) { return OUTLOOK_NEXT.test(w); })) {
      cut = i;
      break;
    }
  }
  const kept = lines.slice(0, cut).filter(function (ln) { return !/^\s*>/.test(ln); });
  return kept.join('\n')
    .split(OPT_OUT).join(' ')
    .replace(/^\s*sent from my .*$/gim, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const GREETING = '(?:hi|hello|hey|dear|hola|ol[áa]|oi|merhaba|cze[śs][ćc]|dzie[ńn] dobry|szia|ahoj|bun[ăa]|salut|good (?:morning|afternoon|evening))';

function optOutKeyword(fresh) {
  let t = String(fresh || '').toLowerCase().trim();
  // A greeting is not the answer: "Hi Abdullah,\nNo thanks." and "Hi Abdullah,
  // no thanks." both open with "no" once the greeting is set aside.
  t = t.replace(new RegExp('^' + GREETING + '\\b[^\\n]{0,60}\\n'), '').trim();
  t = t.replace(new RegExp('^' + GREETING + '\\b[^,\\n]{0,40},\\s*'), '').trim();
  const first = (t.match(/^[^a-zÀ-ɏ]*([a-zÀ-ɏ]+)/) || [])[1] || '';
  if (NO_WORDS.indexOf(first) !== -1) return 'no';
  for (let i = 0; i < OPT_OUT_KEYWORDS.length; i++) {
    const k = OPT_OUT_KEYWORDS[i];
    if (k === 'no') continue;
    if (new RegExp('\\b' + k).test(t)) return k;
  }
  return null;
}

function classify(j) {
  const meta = j.metadata || {};
  const from = str(j.from);
  const fromAddr = addresses(from)[0] || '';
  const fromDomain = domainOf(fromAddr);
  const subject = str(j.subject);
  const raw = str(j.textPlain) || stripHtml(j.textHtml);
  const fresh = freshText(raw);

  const autoSubmitted = str(meta['auto-submitted']).toLowerCase();
  const isBounce = /mailer-daemon|postmaster|mail delivery (?:subsystem|system)/i.test(from) ||
    BOUNCE_SUBJECT.test(subject) ||
    /report-type="?delivery-status/i.test(str(meta['content-type']));
  const isAuto = (autoSubmitted !== '' && autoSubmitted !== 'no') ||
    str(meta['x-autoreply']) !== '' || str(meta['x-autorespond']) !== '' ||
    /^auto_reply$/i.test(str(meta['precedence'])) ||
    AUTO_SUBJECT.test(subject);
  const kw = isBounce || isAuto ? null : optOutKeyword(fresh);
  const classification = isBounce ? 'bounce' : isAuto ? 'auto-reply' : kw ? 'opt-out' : 'reply';

  const threadIds = messageIds(str(meta['in-reply-to']) + ' ' + str(meta['references']));
  const t = new Date(str(j.date)).getTime();
  return {
    message_id: messageId(meta['message-id']) || fallbackId(j),
    received_at: isNaN(t) ? null : new Date(t).toISOString(),
    from_addr: fromAddr,
    from_domain: fromDomain,
    freemail: FREEMAIL.indexOf(fromDomain) !== -1,
    own_domain: fromDomain === OWN_DOMAIN,
    subject: subject.slice(0, 300),
    classification: classification,
    opt_out_keyword: kw,
    // Stored as received (migration 017): a reply draft has to thread to the
    // conversation it answers, and these were parsed and thrown away until
    // 2026-10-08. `thread_ids` is the parsed array Record Inbound matches a
    // lead on; the other two are the headers themselves, because a client that
    // drops its References chain leaves a gap nothing can reconstruct.
    in_reply_to: str(meta['in-reply-to']) || null,
    references_raw: str(meta['references']) || null,
    thread_ids: isBounce ? threadIds.concat(messageIds(raw)).filter(function (x, i, a) { return a.indexOf(x) === i; }) : threadIds,
    mentioned_addrs: isBounce ? addresses(raw).filter(function (a) { return domainOf(a) !== OWN_DOMAIN; }) : [],
    reply_text: fresh.slice(0, 4000),
    body_excerpt: fresh.slice(0, 600),
  };
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------
//
// Two readings of one message, and the ORDER matters (Section 9, Workflow 7).
// build_workflow.py ships code_operator_command.js above this file -- every
// line above its own "Node body" marker, verbatim -- so `operatorCommand` is
// defined here. The operator answers the reply-review email from this same
// mailbox, and that answer is a reply INSIDE the prospect's thread: the review
// email quotes it, so References carries our own Message-ID and Record
// Inbound's strongest matcher would tie the operator's message to the
// prospect's lead. A one-word "no" from the operator would then blocklist a
// real prospect, permanently, with no error anywhere.
//
// So the command is read first, from exactly the text the classifier reads --
// what they wrote above the quoted thread -- and the fork itself is made
// downstream, where the operator's address is known: it lives in the `settings`
// table at runtime and may never be baked into this JSON (migration 008).
const j = $input.item.json;
const payload = classify(j);
return { json: { payload: payload, command: operatorCommand(j, payload.reply_text) } };

// Operator command parsing -- the library half of Classify Inbound.
//
// Section 9, Workflow 7. The operator approves a drafted reply by answering the
// review email: "APPROVE <code>", "REJECT <code>", or "EDIT <code>" followed by
// the replacement text. This file decides, from one INBOX message, whether it
// LOOKS like such a command and whether its authentication passes.
//
// WHY THIS RUNS BEFORE REPLY CLASSIFICATION. code_classify_reply.js treats "no"
// as the first word of a message as an opt-out, and Record Inbound blocklists
// the matched lead's domain permanently. The operator's answers arrive in the
// same mailbox, and an operator who replies to the review email is replying
// INSIDE the prospect's thread -- the review email quotes it, so the References
// header carries our own Message-ID and Record Inbound's strongest matcher
// (`thread`) would tie that message to the prospect's lead. A one-word "no"
// from the operator would then blocklist a real prospect, permanently, with no
// error anywhere. So the command check is first and it is a hard fork: a
// message that is an operator command is never classified as a prospect reply,
// and a message that is not one never reaches the approval path.
//
// WHAT THIS FILE DOES NOT DECIDE. It never compares the sender with the
// operator's address: that address is runtime data in the `settings` table
// (migration 008) and must not be baked into workflow JSON, so the comparison
// happens in SQL, in the same statement that records the command. This file
// reports `from_addr` and the authentication result and lets that statement
// judge. It fails closed everywhere: an unparseable or absent
// Authentication-Results header is not a pass.

// Section 5 / Section 9: an approval counts only if the message's
// authentication results show SPF and DKIM pass. Measured against the real
// header Zoho writes (n8n execution 2336, the Pharmahungary reply):
//
//   authentication-results: mx.zohomail.com;\tdkim=pass;\tspf=pass (zohomail.com:
//   domain of pharmahungary.com designates 185.51.190.242 as permitted sender)
//   smtp.mailfrom=...; dmarc=pass(p=none dis=none) header.from=pharmahungary.com
//
// so the method results are `<method>=<result>` separated by tabs or semicolons,
// each optionally followed by a parenthesised comment. `spf=pass` inside that
// comment text is a real possibility ("... designates ... as permitted sender"
// does not contain it, but nothing stops a future comment from doing so), so
// the comments are stripped before the methods are read.
//
// ARC-Authentication-Results is deliberately NOT consulted. It records what some
// earlier hop claims to have seen, which is a different and weaker statement
// than what our own mail host verified, and this is the gate on sending mail to
// a prospect.
const AUTH_METHODS = ['spf', 'dkim'];

// APPROVE/REJECT/EDIT and the code, on the first line that carries one. Case is
// ignored on the verb (a phone mail client may capitalise or not) but the code's
// alphabet is upper case only -- migration 017 pins the shape.
const COMMAND_VERBS = ['APPROVE', 'REJECT', 'EDIT'];
const CODE_RE = /\bNS-[23456789ABCDEFGHJKMNPQRSTVWXYZ]{10}\b/;
const COMMAND_RE = /^\s*(approve|reject|edit)\b[\s:,-]*(NS-[23456789abcdefghjkmnpqrstvwxyz]{10})?\s*(.*)$/i;

function opStr(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

// Drop every parenthesised comment, including nested ones, so a method result is
// read from the header's own tokens and never from prose inside a comment.
function stripComments(s) {
  let out = '';
  let depth = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charAt(i);
    if (c === '(') { depth++; continue; }
    if (c === ')') { if (depth > 0) depth--; continue; }
    if (depth === 0) out += c;
  }
  return out;
}

// One Authentication-Results header (or several, joined) -> { spf: bool, dkim: bool }.
// A method named more than once must pass EVERY time: two headers disagreeing
// about SPF is not a pass.
function authResults(header) {
  const text = stripComments(opStr(header)).toLowerCase();
  const seen = {};
  const re = /([a-z][a-z0-9-]*)\s*=\s*([a-z]+)/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const method = m[1];
    const result = m[2];
    if (AUTH_METHODS.indexOf(method) === -1) continue;
    const ok = result === 'pass';
    seen[method] = seen[method] === undefined ? ok : (seen[method] && ok);
  }
  const out = {};
  for (let i = 0; i < AUTH_METHODS.length; i++) {
    out[AUTH_METHODS[i]] = seen[AUTH_METHODS[i]] === true;
  }
  return out;
}

// What the operator wrote, above any quoted thread. freshText() already does
// that cut for prospect replies; the command parser is handed the same text so
// an APPROVE quoted back inside a later message is not re-read as a command.
//
// EDIT's replacement is everything after the code -- the rest of that line and
// every following line of fresh text. Blank means "no replacement given", which
// the caller refuses rather than guessing.
function parseCommand(fresh) {
  const lines = opStr(fresh).replace(/\r\n?/g, '\n').split('\n');
  for (let i = 0; i < lines.length; i++) {
    const m = COMMAND_RE.exec(lines[i]);
    if (!m) continue;
    const verb = m[1].toUpperCase();
    if (COMMAND_VERBS.indexOf(verb) === -1) continue;

    // The verb is on this line. The code is normally on it too; accept it on a
    // following line as well, because a client may wrap a long line. Whatever
    // follows the code -- the rest of its line and every later line -- is the
    // replacement text, for EDIT.
    let code = null;
    let after = '';
    if (m[2]) {
      code = m[2].toUpperCase();
      after = [opStr(m[3])].concat(lines.slice(i + 1)).join('\n');
    } else {
      const tail = lines.slice(i + 1).join('\n');
      const hit = CODE_RE.exec(tail.toUpperCase());
      if (hit) {
        code = hit[0];
        after = tail.slice(hit.index + hit[0].length);
      } else {
        after = [opStr(m[3])].concat(lines.slice(i + 1)).join('\n');
      }
    }
    after = after.trim();
    return {
      is_command: true,
      command: verb,
      code: code,
      // Only EDIT carries a replacement; migration 017 refuses one on the others.
      replacement: verb === 'EDIT' ? (after || null) : null,
    };
  }
  return { is_command: false, command: null, code: null, replacement: null };
}

// The whole decision for one message, as the SQL statement needs it. `sender_ok`
// is left to SQL -- see the header comment.
function operatorCommand(j, fresh) {
  const meta = (j && j.metadata) || {};
  const parsed = parseCommand(fresh);
  const auth = authResults(meta['authentication-results']);

  // Why it would be refused, in the order the operator would want to hear it.
  // `sender` is the one reason this file cannot rule on, so it is reported as a
  // pending check rather than a verdict.
  let refused = null;
  if (parsed.is_command && !parsed.code) refused = 'no one-time code in the message';
  else if (parsed.is_command && !auth.spf) refused = 'the message\'s authentication results do not show SPF pass';
  else if (parsed.is_command && !auth.dkim) refused = 'the message\'s authentication results do not show DKIM pass';
  else if (parsed.is_command && parsed.command === 'EDIT' && !parsed.replacement) {
    refused = 'EDIT with no replacement text after the code';
  }

  return {
    is_command: parsed.is_command,
    command: parsed.command,
    code: parsed.code,
    replacement: parsed.replacement,
    spf_pass: auth.spf,
    dkim_pass: auth.dkim,
    refused_reason: refused,
  };
}

// ---------------------------------------------------------------------------
// The decision -- Decide Command, n8n Code node (Run Once for Each Item).
//
// Everything above this point can be read off one message. The three things
// that cannot -- is the sender the operator's address, does this code exist, is
// it unused and unexpired -- are database facts, and "Load Command Context" has
// just read them in one read-only snapshot. This section turns that snapshot
// into a verdict.
//
// It is NOT the last line of defence. "Apply Operator Command" re-derives the
// operator address from `settings`, re-checks the code through
// reply_approval_usable(), and the table itself CHECKs that `accepted` is only
// possible with SPF, DKIM and the sender all passing (migration 017). A bug
// here can refuse a real approval; it cannot accept a forged one -- the same
// direction of safety as Decide Send and Claim Send.
//
// THREE SEPARATE QUESTIONS, and conflating them is how a prospect's reply would
// get lost, or a prospect's domain blocklisted by the operator's own "no":
//
//   record   -- is this message command-SHAPED? Then it goes into
//               operator_commands, accepted or refused. The refused rows are
//               the point: a spoofed sender, a failed SPF or DKIM, an unknown,
//               expired or reused code (migration 017).
//   handled  -- is it really FROM the operator (SPF + DKIM + the operator's own
//               address)? Then it is operator mail and is never classified as a
//               prospect reply. Anything else falls through to Record Inbound,
//               which is right: a message that merely looks like a command and
//               did not come from the operator may well be a prospect writing.
//   accepted -- handled, and nothing refused it. Only then does a draft move.
//
// A message from the operator that is NOT command-shaped -- a plain "no" --
// records nothing and is handled=false, so it reaches Record Inbound. That
// statement has its own guard: a message from the operator's address is never
// matched to a lead, so the "no" cannot blocklist a prospect (Workflow 6).

// Section 5, substituted at build time: the signature every outbound message
// carries, and the one-URL cap. An EDIT replaces the reply's core text and
// keeps the frame around it, so the operator's own words go out under the same
// signature and the send path's checks still find what they look for.
const CMD_SIGNATURE = "Abdullah Amir\nFounder, Amitrix Labs\n+923178485713";
const CMD_MAX_URLS = 1;
const CMD_URL_RE = /\b(?:https?:\/\/|www\.)[^\s<>()]+/gi;

const CMD_OUTCOME = { APPROVE: 'approved', REJECT: 'rejected', EDIT: 'edited' };

function cmdUrls(v) {
  return (opStr(v).match(CMD_URL_RE) || []).length;
}

function cmdMs(v) {
  if (v === null || v === undefined || v === '') return null;
  const t = new Date(v).getTime();
  return isNaN(t) ? null : t;
}

// The reply as it will go out, with the operator's text in place of the
// model's. The frame is taken from the stored draft, never regenerated: the
// greeting is its first paragraph, and everything from the signature onward --
// the signature itself and the quoted message being answered -- is kept
// verbatim. So an EDIT changes exactly the words the operator rewrote.
function framedEdit(body, replacement) {
  const b = String(body === null || body === undefined ? '' : body).replace(/\r\n?/g, '\n');
  const at = b.indexOf(CMD_SIGNATURE);
  const tail = at === -1 ? '' : b.slice(at + CMD_SIGNATURE.length);
  const firstBreak = b.indexOf('\n\n');
  const greeting = firstBreak === -1 ? 'Hello,' : b.slice(0, firstBreak).trim();
  return [greeting, '', opStr(replacement), '', CMD_SIGNATURE].join('\n') + tail;
}

function commandDecision(ctx) {
  const cmd = (ctx && ctx.command) || {};
  const isCommand = cmd.is_command === true;
  const spf = cmd.spf_pass === true;
  const dkim = cmd.dkim_pass === true;
  const operator = opStr(ctx.operator_email).toLowerCase();
  const from = opStr(ctx.payload && ctx.payload.from_addr).toLowerCase();
  const senderOk = operator !== '' && from !== '' && from === operator;
  const authenticated = isCommand && spf && dkim && senderOk;
  const verb = opStr(cmd.command).toUpperCase();
  const code = opStr(cmd.code).toUpperCase() || null;
  const now = cmdMs(ctx.now);
  const expires = cmdMs(ctx.code_expires_at);

  let edited = null;
  let refused = null;
  if (!isCommand) {
    refused = 'not an operator command';
  } else if (cmd.refused_reason) {
    // No code in the message, SPF or DKIM not passing, or EDIT with no
    // replacement text: decided from the message alone, above.
    refused = cmd.refused_reason;
  } else if (!senderOk) {
    refused = operator
      ? 'not sent from the operator address'
      : 'no operator address is configured (settings.operator_email)';
  } else if (!ctx.code_found) {
    refused = 'no such one-time code';
  } else if (ctx.code_used_at) {
    refused = 'that one-time code was already used at ' + opStr(ctx.code_used_at) +
      ' (' + opStr(ctx.code_outcome) + ')';
  } else if (expires !== null && now !== null && expires <= now) {
    refused = 'that one-time code expired at ' + opStr(ctx.code_expires_at);
  } else if (opStr(ctx.draft_status) !== 'pending') {
    refused = 'draft ' + opStr(ctx.draft_id) + ' is no longer waiting (it is ' +
      (opStr(ctx.draft_status) || 'gone') + ')';
  } else if (verb === 'EDIT') {
    edited = framedEdit(ctx.draft_body, cmd.replacement);
    if (cmdUrls(edited) > CMD_MAX_URLS) {
      // Section 5 allows one plain URL. Refused rather than sent -- and the
      // code is NOT used, so the same code still works for a corrected EDIT.
      refused = 'that replacement carries ' + cmdUrls(edited) + ' links; Section 5 allows ' +
        CMD_MAX_URLS + '. The code is still good: send EDIT again with at most one link.';
      edited = null;
    }
  }

  // `accepted` here is a PROPOSAL. Apply Operator Command re-derives the
  // operator address, re-checks the code through reply_approval_usable() and
  // only then moves the draft; what actually happened is what that statement
  // returns, and Build Command Ack writes the acknowledgement from THAT, never
  // from this.
  const accepted = authenticated && refused === null;

  return {
    // operator_commands gets a row for anything command-shaped.
    record: isCommand,
    // Operator mail is never a prospect reply.
    handled: authenticated,
    accepted: accepted,
    command: verb || null,
    code: code,
    replacement: verb === 'EDIT' ? (cmd.replacement || null) : null,
    edited_body: edited,
    spf_pass: spf,
    dkim_pass: dkim,
    sender_ok: senderOk,
    refused_reason: refused,
    outcome: accepted ? (CMD_OUTCOME[verb] || null) : null,
    draft_id: ctx.draft_id === undefined ? null : ctx.draft_id,
    code_kind: ctx.code_kind === undefined ? null : ctx.code_kind,
  };
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

const ctx = $input.item.json;
const decision = commandDecision(ctx);
return { json: Object.assign({}, decision, { payload: ctx.payload, command_parse: ctx.command }) };

// Build Command Ack -- n8n Code node (Run Once for Each Item).
//
// Section 9, Workflow 7. The operator answered the reply-review email with
// APPROVE / REJECT / EDIT and a one-time code; "Apply Operator Command" has
// just recorded what arrived and done whatever it was allowed to do. This node
// writes the one-line answer back.
//
// Built from that statement's returned row, never from Decide Command's
// proposal: the statement re-derives the operator address from `settings`,
// re-checks the code through reply_approval_usable() and only then moves the
// draft, so the row is what actually happened. A draft that changed underneath
// between the read and the write is refused there, and this says so.
//
// WHO GETS AN ANSWER, and this is a security decision, not a courtesy:
//
//   * an authenticated operator does -- accepted or refused. A refusal they
//     never see is a code they will keep retyping.
//   * nobody else does. A message that failed SPF or DKIM, or that did not come
//     from the operator's address, is recorded in operator_commands as refused
//     and answered with silence. Answering it would turn the mailbox into an
//     oracle for guessing codes, and would send mail to whatever address a
//     forgery chose to put in From.
//   * a re-delivered message does not, because `recorded` is false the second
//     time -- operator_commands is keyed on Message-ID, so the row was inserted
//     once and this fires once (the role inbound_messages plays for a prospect
//     message).
//
// The answer goes to the address in `settings` (migration 008), read at runtime
// by the statement upstream, so no address is baked into this workflow. Like a
// reply notification it goes only to the operator, so it uses no warm-up slot.

// One bare address -- the build's rule, and migration 008's CHECK.
const ACK_ADDRESS = /^[^\s@<>(),;:"']+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$/;

function aStr(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function ackAddress(r) {
  const a = aStr(r.notify_to).toLowerCase();
  return ACK_ADDRESS.test(a) ? a : '';
}

function commandAck(r) {
  const to = ackAddress(r);
  const verb = aStr(r.command).toUpperCase();
  const code = aStr(r.code);
  const accepted = r.accepted === true;
  const lines = [];

  if (accepted) {
    lines.push(verb + ' accepted for draft ' + aStr(r.draft_id) +
      (aStr(r.code_kind) ? ' (' + aStr(r.code_kind) + ')' : '') + '.');
    lines.push('');
    if (verb === 'APPROVE') {
      lines.push('The draft is approved and goes out on the next send tick. A reply skips the');
      lines.push('warm-up ceiling and the recipient\'s business hours; it never skips the');
      lines.push('blocklist (Section 9, Workflow 7).');
    } else if (verb === 'EDIT') {
      lines.push('Your text replaced the draft\'s, under the same greeting and the same signature,');
      lines.push('and the draft is approved. It goes out on the next send tick.');
      lines.push('');
      lines.push('WHAT WILL BE SENT');
      lines.push('');
      lines.push(aStr(r.edited_body) || '(nothing recorded -- check draft ' + aStr(r.draft_id) + ')');
    } else {
      lines.push('The draft is rejected (bad draft) and nothing will be sent. Their message stays');
      lines.push('on the lead. To have a reply drafted again, delete that draft\'s row from');
      lines.push('reply_approvals.');
    }
  } else {
    lines.push((verb || 'That command') + ' was REFUSED.');
    lines.push('');
    lines.push('Reason: ' + (aStr(r.refused_reason) || 'not recorded'));
    lines.push('');
    lines.push('Nothing changed and nothing will be sent. Every command this mailbox receives is');
    lines.push('recorded in operator_commands, accepted or refused.');
  }

  lines.push('');
  lines.push('Code:      ' + (code || '(none in the message)'));
  lines.push('Draft:     ' + (aStr(r.draft_id) || '-') +
    (aStr(r.draft_status) ? ' (' + aStr(r.draft_status) + ')' : ''));
  lines.push('Your mail: ' + aStr(r.message_id));
  lines.push('Subject:   ' + aStr(r.subject));
  lines.push('SPF/DKIM:  ' + (r.spf_pass === true ? 'pass' : 'FAIL') + ' / ' +
    (r.dkim_pass === true ? 'pass' : 'FAIL'));
  lines.push('');
  lines.push('-- Nova Scout (Workflow 7). Sent only to this address; it uses no warm-up slot.');

  return {
    notify: Boolean(r.notify) && to !== '',
    notify_to: to,
    subject: ('[Nova Scout] ' + (accepted ? verb + ' ok' : 'command refused') +
      (code ? ' -- ' + code : '')).slice(0, 200),
    text: lines.join('\n'),
  };
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

return { json: commandAck($input.item.json) };

// Detect Positive Signal -- n8n Code node (Run Once for Each Item).
//
// Section 9, Workflow 6 reply notification: a deterministic, no-model check
// (build rule 3, same as Classify Inbound) of what the operator notification
// says about a reply Classify Inbound / Record Inbound has ALREADY labelled --
// it does not change that label, and Record Inbound's own SQL is untouched.
//
// Only a classification of 'reply' is scored. Classify Inbound's own
// precedence -- bounce > auto-reply > opt-out > reply -- has already spoken
// for the other three, and scoring a stray positive word inside one of them
// would contradict the decision already made: "Yes, please remove me." is an
// OPT-OUT on "remove" (code_classify_reply.js, unchanged) before this node
// ever runs, and the "Yes" in it is never read as a positive signal here.

const POSITIVE_PATTERNS = [
  [/\byes\b/, 'yes'],
  [/\byeah\b/, 'yeah'],
  [/\byep\b/, 'yep'],
  [/\bsure\b/, 'sure'],
  [/\binterested\b/, 'interested'],
  [/\bsounds good\b/, 'sounds good'],
  [/\bsounds great\b/, 'sounds great'],
  [/\bsend it\b/, 'send it'],
  [/\bsend (?:it |that )?over\b/, 'send over'],
  [/\bgo ahead\b/, 'go ahead'],
  [/\blet'?s (?:talk|chat|do it)\b/, "let's talk"],
  [/\bhappy to\b/, 'happy to'],
  [/\bworks for me\b/, 'works for me'],
  [/\bcount me in\b/, 'count me in'],
];

function str(v) {
  return v === null || v === undefined ? '' : String(v);
}

function positiveSignal(r) {
  if (r.classification !== 'reply') return { signal: 'neutral', signal_keyword: null };
  const t = str(r.body_excerpt).toLowerCase();
  for (let i = 0; i < POSITIVE_PATTERNS.length; i++) {
    const pair = POSITIVE_PATTERNS[i];
    if (pair[0].test(t)) return { signal: 'positive', signal_keyword: pair[1] };
  }
  return { signal: 'neutral', signal_keyword: null };
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

const r = $input.item.json;
return { json: Object.assign({}, r, positiveSignal(r)) };

// Build Operator Notification -- n8n Code node (Run Once for Each Item).
//
// Section 9, Workflow 6, with HubSpot deferred: "a short internal notification
// email fires to the operator's own inbox (not the outreach mailbox) the moment
// a reply lands -- reusing the same SMTP capability this workflow needs anyway".
//
// Built from the row Record Inbound returned. That row is only marked `notify`
// the FIRST time a message is recorded (inbound_messages is keyed on
// Message-ID), so an IMAP re-delivery cannot notify twice.
//
// The address arrives on that same row: Record Inbound reads it at RUNTIME from
// the `settings` table (migration 008, written from .env by sync_settings.py).
// Nothing is baked into this node, so no address lands in the committed
// workflow JSON. Unset, or not one address, means nobody to tell: the reply is
// still recorded, the lead still leaves the send queue and the opt-out is still
// blocklisted -- only this email is skipped.
//
// The positive/neutral signal comes from Detect Positive Signal, upstream --
// a deterministic keyword check of the reply's own text (build rule 3, no
// model). It is display only, and only ever shown for classification ===
// 'reply': an opt-out or bounce is never scored (see that node's header).
//
// Assets: one link today, the one-pager. No recording link -- that asset
// does not exist and is not planned right now. ASSETS is a list precisely so
// a second asset, once one exists, is one more entry here -- not a rebuild.

// One bare address -- the build's rule, and migration 008's CHECK.
const ADDRESS = /^[^\s@<>(),;:"']+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+$/;

const LABEL = { 'reply': 'REPLY', 'opt-out': 'OPT-OUT', 'bounce': 'BOUNCE' };
const SIGNAL_LABEL = { 'positive': 'POSITIVE', 'neutral': 'NEUTRAL' };

// Which one-pager depends on who replied (2026-10-09): a CRO gets the CRO
// one-pager, a research site or an SMO the site version -- both hosted the same
// way, from the repo's main branch. Record Inbound supplies company_type (the
// same CRO / site / SMO definition Drafting uses); anything else is a CRO.
const ONE_PAGER_BASE = 'https://raw.githubusercontent.com/abdullahamir2308/nova-scout/main/';
const ASSETS_BY_TYPE = {
  CRO: [{ label: 'One-pager', url: ONE_PAGER_BASE + 'nova-one-pager.docx' }],
  site: [{ label: 'One-pager (research sites)', url: ONE_PAGER_BASE + 'nova-one-pager-sites.docx' }],
  SMO: [{ label: 'One-pager (research sites)', url: ONE_PAGER_BASE + 'nova-one-pager-sites.docx' }],
};
function assetsFor(r) {
  return ASSETS_BY_TYPE[str(r.company_type)] || ASSETS_BY_TYPE.CRO;
}

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function operatorAddress(r) {
  const a = str(r.operator_email).toLowerCase();
  return ADDRESS.test(a) ? a : '';
}

function notification(r) {
  const to = operatorAddress(r);
  const what = LABEL[r.classification] || str(r.classification).toUpperCase();
  const who = str(r.company_name) || str(r.domain) || str(r.from_addr);
  const lines = [];
  if (r.classification === 'opt-out') {
    const blocked = Array.isArray(r.blocklisted) && r.blocklisted.length ? r.blocklisted.join(', ') : 'nothing new (already listed)';
    lines.push('Opt-out detected -- matched "' + str(r.opt_out_keyword) + '". Blocklisted: ' + blocked + '.');
    lines.push('Nothing more will be sent to this domain. If they did not mean it, delete the row from `blocklist` by hand.');
  } else if (r.classification === 'bounce') {
    lines.push('A send to this lead bounced. Its follow-ups are stopped; the contact address needs checking.');
  } else {
    lines.push('A lead replied. Its follow-ups are stopped and it is in the replied_queue view in NocoDB.');
  }
  lines.push('');
  lines.push('Company:   ' + (str(r.company_name) || '?'));
  lines.push('Domain:    ' + str(r.domain) + (str(r.country) ? ' (' + str(r.country) + ')' : ''));
  lines.push('Fit score: ' + (r.fit_score === null || r.fit_score === undefined ? '?' : r.fit_score));
  lines.push('Contact:   ' + (str(r.contact_email) || '?'));
  lines.push('From:      ' + str(r.from_addr));
  lines.push('Subject:   ' + str(r.subject));
  lines.push('Received:  ' + str(r.received_at));
  lines.push('Matched:   ' + str(r.matched_by));
  if (r.classification === 'reply') {
    const sig = SIGNAL_LABEL[r.signal] || 'NEUTRAL';
    lines.push('Signal:    ' + sig + (r.signal_keyword ? ' (matched "' + str(r.signal_keyword) + '")' : ''));
  }
  lines.push('');
  lines.push('What they wrote:');
  lines.push('');
  lines.push(str(r.body_excerpt) || '(no text above the quoted thread)');
  lines.push('');
  lines.push('Assets:');
  assetsFor(r).forEach(function (a) { lines.push('  ' + a.label + ': ' + a.url); });
  return {
    notify: Boolean(r.notify) && to !== '',
    notify_to: to,
    subject: ('[Nova Scout] ' + what + ' from ' + who).slice(0, 200),
    text: lines.join('\n'),
  };
}

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

return { json: notification($input.item.json) };
